"use strict";class offcanvas{constructor(){this.buf_params=Joomla.getOptions("buf.config").params,this.ocbutton=document.querySelector("#bufoc_button"),this.occanvas=document.querySelector("#bsOffcanvas"),this.init()}init(){0==this.buf_params.offcanvas?this.buf_debug("offcanvas disabled"):(this.addEventListeners(),document.documentElement.classList.add("buf_canvas"))}addEventListeners(){this.buf_debug("offcanvas addEventListeners"),this.ocbutton.addEventListener("click",()=>this.offcanvasClick()),this.occanvas&&(this.occanvas.addEventListener("show.bs.offcanvas",()=>this.onShow()),this.occanvas.addEventListener("hidden.bs.offcanvas",()=>this.onHidden()))}offcanvasClick(){this.buf_debug("offcanvasClick"),this.ocbutton.classList.toggle("is-active")}onShow(){this.buf_debug("offcanvas opening — inert removed"),this.occanvas.removeAttribute("inert")}onHidden(){this.buf_debug("offcanvas closed — inert restored"),this.occanvas.setAttribute("inert","")}buf_debug(s){this.buf_params.debug&&console.log("BUF |-*-| "+s)}}new offcanvas;